"use client"

import { useEffect, useState, useRef } from "react"
import { Mail, Phone, Github, Linkedin, Twitter, Instagram } from "lucide-react"
import imge from "../assets/WhatsApp_Image_2025-07-07_at_5.30.07_PM-removebg-preview.png"

export default function HeroSection() {
  const [scrollY, setScrollY] = useState(0)
  const [isVisible, setIsVisible] = useState(false)
  const [clickedSocial, setClickedSocial] = useState(null)
  const sectionRef = useRef(null)

  useEffect(() => {
    const handleScroll = () => setScrollY(window.scrollY)
    window.addEventListener("scroll", handleScroll)

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true)
        }
      },
      { threshold: 0.1 },
    )

    if (sectionRef.current) {
      observer.observe(sectionRef.current)
    }

    const timer = setTimeout(() => setIsVisible(true), 300)

    return () => {
      window.removeEventListener("scroll", handleScroll)
      observer.disconnect()
      clearTimeout(timer)
    }
  }, [])

  const handleSocialClick = (platform) => {
    setClickedSocial(platform)
    setTimeout(() => setClickedSocial(null), 300)

    const urls = {
      github: "https://github.com/badreddine55/",
      linkedin: "https://www.linkedin.com/in/badr-eddine-252704319/",
      twitter: "https://x.com/Badr_eddine55",
      instagram: "https://www.instagram.com/badr_dy/",
    }

    if (urls[platform]) {
      window.open(urls[platform], "_blank")
    }
  }

  return (
    <section ref={sectionRef} className="relative min-h-screen overflow-hidden pt-16 md:pt-20">
      {/* Spline 3D Background with Parallax */}
      <div
        className="absolute inset-0 w-full h-full"
        style={{
          transform: `translateY(${scrollY * 0.5}px)`,
        }}
      >
        <iframe
          src="https://my.spline.design/cubes-A0T7CP5J2qsawolli9BlhInB/"
          className="w-full h-full border-0"
          title="3D Cubes Scene"
        />
        <div className="absolute inset-0 pointer-events-none">
          <div
            className="absolute inset-0"
            style={{
              background: `
                linear-gradient(
                  135deg,
                  rgba(0, 0, 0, 0.7) 0%,
                  rgba(0, 0, 0, 0.4) 50%,
                  rgba(0, 0, 0, 0.8) 100%
                )
              `,
            }}
          />
        </div>
      </div>

      {/* Floating Elements */}
      <div className="absolute inset-0 pointer-events-none overflow-hidden">
        <div
          className={`absolute top-20 left-4 md:left-10 w-2 h-2 bg-teal-400 rounded-full transition-all duration-1000 ${
            isVisible ? "opacity-60 animate-pulse" : "opacity-0"
          }`}
          style={{
            transform: `translateY(${scrollY * 0.3}px)`,
          }}
        />
        <div
          className={`absolute top-40 right-8 md:right-20 w-1 h-1 bg-white rounded-full transition-all duration-1200 delay-300 ${
            isVisible ? "opacity-40 animate-bounce" : "opacity-0"
          }`}
          style={{
            transform: `translateY(${scrollY * 0.7}px)`,
          }}
        />
        <div
          className={`absolute bottom-40 left-1/4 w-1.5 h-1.5 bg-teal-300 rounded-full transition-all duration-1400 delay-600 ${
            isVisible ? "opacity-50 animate-ping" : "opacity-0"
          }`}
          style={{
            transform: `translateY(${scrollY * 0.4}px)`,
          }}
        />
      </div>

      {/* Content */}
      <div className="relative z-10 container mx-auto px-4 sm:px-6 lg:px-16 min-h-screen flex items-center">
        <div className="w-full max-w-7xl mx-auto">
          {/* Top Section - Small paragraph and big name */}
          <div className="mb-8 md:mb-12 text-center lg:text-left">
            {/* Small paragraph with slide-in animation */}
            <div className="overflow-hidden">
              <p
                className={`text-gray-400 text-base md:text-lg mb-4 transform transition-all duration-1000 delay-200 ${
                  isVisible ? "translate-y-0 opacity-100" : "translate-y-8 opacity-0"
                }`}
              >
                Hey👋, I'm a Full Stack Developer
              </p>
            </div>

            {/* Large name with staggered letter animation */}
            <div className="overflow-hidden">
              <h1
                className={`text-3xl sm:text-4xl md:text-6xl lg:text-7xl xl:text-8xl 2xl:text-9xl font-bold gradient-text leading-none transform transition-all duration-1200 delay-500 ${
                  isVisible ? "translate-y-0 opacity-100 scale-100" : "translate-y-12 opacity-0 scale-95"
                }`}
                style={{
                  transform: `translateY(${scrollY * 0.1}px)`,
                  background: "linear-gradient(135deg, #ffffff 0%, #06b6d4 50%, #10b981 100%)",
                  WebkitBackgroundClip: "text",
                  WebkitTextFillColor: "transparent",
                  backgroundClip: "text",
                }}
              >
                BADR EDDINE DIYAF
              </h1>
            </div>
          </div>

          {/* Main Content Grid */}
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 lg:gap-12 items-start">
            {/* Left Column - Contact Info (Mobile: Top, Desktop: Left) */}
            <div
              className={`order-3 lg:order-1 space-y-4 md:space-y-6 transform transition-all duration-1000 delay-700 ${
                isVisible ? "translate-x-0 opacity-100" : "-translate-x-8 opacity-0"
              }`}
            >
              <div className="space-y-2 text-sm">
                <div className="flex items-center gap-2 group cursor-pointer hover:scale-105 transition-transform duration-300">
                  <Mail className="w-4 h-4 text-teal-500 group-hover:animate-bounce" />
                  <span className="text-white group-hover:text-teal-400 transition-colors duration-300">
                    beddine330@gmail.com
                  </span>
                </div>
                <div className="flex items-center gap-2 group cursor-pointer hover:scale-105 transition-transform duration-300">
                  <Phone className="w-4 h-4 text-teal-500 group-hover:animate-bounce" />
                  <span className="text-white group-hover:text-teal-400 transition-colors duration-300">
                    +212 701 708 363
                  </span>
                </div>
              </div>

              {/* Description Text - Mobile Only */}
              <div className="lg:hidden relative">
                <p className="text-sm md:text-base text-gray-400 leading-relaxed hover:text-gray-300 transition-colors duration-300">
                  Développeur web passionné, spécialisé en développement full stack et conception UI/UX, avec une forte
                  aptitude à créer des applications responsives, optimisées et centrées sur l'utilisateur.
                </p>
              </div>

              {/* Download CV Button - Mobile */}
              <div className="lg:hidden">
                <button
                  onClick={() => {
                    const link = document.createElement("a")
                    link.href = "src/assets/BadrEddineDiyaf.pdf"
                    link.download = "Badr_Eddine_Diyaf_CV.pdf"
                    link.click()
                  }}
                  className="w-full group relative px-6 py-3 bg-transparent border-2 border-teal-500 text-teal-400 font-semibold rounded-full overflow-hidden transition-all duration-300 hover:scale-105 hover:bg-teal-500 hover:text-white hover:shadow-2xl hover:shadow-teal-500/25"
                >
                  <div className="absolute inset-0 bg-teal-500 scale-x-0 group-hover:scale-x-100 transition-transform duration-300 origin-left"></div>
                  <span className="relative z-10 flex items-center justify-center gap-2">
                    <svg
                      className="w-4 h-4 transform group-hover:animate-bounce"
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
                      />
                    </svg>
                    Download CV
                  </span>
                </button>
              </div>
            </div>

            {/* Center Column - Image */}
            <div
              className={`order-1 lg:order-2 flex justify-center transform transition-all duration-1200 delay-900 ${
                isVisible ? "translate-y-0 opacity-100 scale-100" : "translate-y-12 opacity-0 scale-95"
              }`}
            >
              <div className="relative w-full max-w-xs sm:max-w-sm group">
                <div
                  className="relative rounded-2xl overflow-hidden bg-black/20 backdrop-blur-sm border border-white/10 hover:border-teal-500/50 transition-all duration-500 hover:scale-105 hover:shadow-2xl hover:shadow-teal-500/20"
                  style={{
                    transform: `translateY(${scrollY * -0.1}px)`,
                  }}
                >
                  <img
                    src={imge || "/placeholder.svg"}
                    alt="Badr Eddine Diyaf"
                    className="w-full h-auto rounded-2xl transition-all duration-500"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent group-hover:from-black/40 transition-all duration-500"></div>

                  {/* Social Icons Inside Image - Desktop Only */}
                  <div className="hidden lg:flex absolute bottom-6 left-6 gap-3 opacity-0 group-hover:opacity-100 transform translate-y-4 group-hover:translate-y-0 transition-all duration-500">
                    <button
                      onClick={() => handleSocialClick("github")}
                      className={`w-10 h-10 bg-black/80 backdrop-blur-sm border border-white/20 hover:border-teal-500 hover:bg-teal-500/20 rounded-full flex items-center justify-center transition-all duration-300 hover:scale-110 hover:-translate-y-1 group/github ${
                        clickedSocial === "github" ? "animate-pulse scale-125" : ""
                      }`}
                    >
                      <Github className="w-4 h-4 text-white group-hover/github:text-teal-400 transition-colors duration-300" />
                    </button>
                    <button
                      onClick={() => handleSocialClick("linkedin")}
                      className={`w-10 h-10 bg-black/80 backdrop-blur-sm border border-white/20 hover:border-blue-500 hover:bg-blue-500/20 rounded-full flex items-center justify-center transition-all duration-300 hover:scale-110 hover:-translate-y-1 group/linkedin ${
                        clickedSocial === "linkedin" ? "animate-pulse scale-125" : ""
                      }`}
                    >
                      <Linkedin className="w-4 h-4 text-white group-hover/linkedin:text-blue-400 transition-colors duration-300" />
                    </button>
                    <button
                      onClick={() => handleSocialClick("twitter")}
                      className={`w-10 h-10 bg-black/80 backdrop-blur-sm border border-white/20 hover:border-sky-500 hover:bg-sky-500/20 rounded-full flex items-center justify-center transition-all duration-300 hover:scale-110 hover:-translate-y-1 group/twitter ${
                        clickedSocial === "twitter" ? "animate-pulse scale-125" : ""
                      }`}
                    >
                      <Twitter className="w-4 h-4 text-white group-hover/twitter:text-sky-400 transition-colors duration-300" />
                    </button>
                    <button
                      onClick={() => handleSocialClick("instagram")}
                      className={`w-10 h-10 bg-black/80 backdrop-blur-sm border border-white/20 hover:border-pink-500 hover:bg-pink-500/20 rounded-full flex items-center justify-center transition-all duration-300 hover:scale-110 hover:-translate-y-1 group/instagram ${
                        clickedSocial === "instagram" ? "animate-pulse scale-125" : ""
                      }`}
                    >
                      <Instagram className="w-4 h-4 text-white group-hover/instagram:text-pink-400 transition-colors duration-300" />
                    </button>
                  </div>

                  <div className="absolute inset-0 rounded-2xl border-2 border-teal-500/0 group-hover:border-teal-500/30 transition-all duration-500"></div>
                </div>

                <div className="absolute -top-2 -right-2 w-4 h-4 bg-teal-400 rounded-full animate-ping opacity-75 group-hover:opacity-0 transition-opacity duration-300"></div>
              </div>
            </div>

            {/* Right Column - Description and Actions (Desktop Only) */}
            <div
              className={`hidden lg:block order-2 lg:order-3 space-y-8 transform transition-all duration-1000 delay-1100 ${
                isVisible ? "translate-x-0 opacity-100" : "translate-x-8 opacity-0"
              }`}
            >
              {/* Description Text */}
              <div className="relative">
                <p
                  className="text-lg text-gray-400 leading-relaxed hover:text-gray-300 transition-colors duration-300 relative z-10"
                  style={{
                    transform: `translateY(${scrollY * 0.05}px)`,
                  }}
                >
                  I build fast, scalable, and user-friendly web applications using modern JavaScript frameworks —
                  combining React on the frontend and Node.js on the server-side.
                </p>

                <div className="absolute -left-4 top-0 w-1 h-full bg-gradient-to-b from-teal-500/50 to-transparent rounded-full"></div>
                <div className="absolute -right-2 top-2 w-2 h-2 bg-teal-400/60 rounded-full animate-pulse"></div>
              </div>

              {/* Download CV Button */}
              <div
                className={`transform transition-all duration-1000 delay-1300 ${
                  isVisible ? "translate-y-0 opacity-100" : "translate-y-4 opacity-0"
                }`}
              >
                <button
                  onClick={() => {
                    const link = document.createElement("a")
                    link.href = "src/assets/BadrEddineDiyaf.pdf"
                    link.download = "Badr_Eddine_Diyaf_CV.pdf"
                    link.click()
                  }}
                  className="group relative px-8 py-4 bg-transparent border-2 border-teal-500 text-teal-400 font-semibold rounded-full overflow-hidden transition-all duration-300 hover:scale-105 hover:bg-teal-500 hover:text-white hover:shadow-2xl hover:shadow-teal-500/25 active:scale-95"
                >
                  <div className="absolute inset-0 bg-teal-500 scale-x-0 group-hover:scale-x-100 transition-transform duration-300 origin-left"></div>
                  <div className="absolute inset-0 rounded-full bg-white/20 scale-0 group-active:scale-100 transition-transform duration-200"></div>
                  <span className="relative z-10 flex items-center gap-2">
                    <svg
                      className="w-4 h-4 transform group-hover:animate-bounce"
                      fill="none"
                      stroke="currentColor"
                      viewBox="0 0 24 24"
                    >
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth={2}
                        d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
                      />
                    </svg>
                    Download CV
                  </span>
                  <div className="absolute -inset-1 bg-teal-500/30 rounded-full opacity-0 group-hover:opacity-100 blur-sm transition-opacity duration-300 -z-10"></div>
                </button>
              </div>

              {/* Decorative Line */}
              <div
                className={`flex justify-center transform transition-all duration-1000 delay-1500 ${
                  isVisible ? "translate-y-0 opacity-100" : "translate-y-4 opacity-0"
                }`}
              >
                <div className="flex items-center gap-2">
                  <div className="w-8 h-0.5 bg-gradient-to-r from-transparent via-teal-400 to-transparent"></div>
                  <div className="w-2 h-0.5 bg-teal-400 rounded-full animate-pulse"></div>
                  <div className="w-8 h-0.5 bg-gradient-to-r from-transparent via-teal-400 to-transparent"></div>
                </div>
              </div>
            </div>

            {/* Mobile Social Icons */}
            <div className="order-2 lg:hidden flex justify-center gap-4">
              <button
                onClick={() => handleSocialClick("github")}
                className="w-12 h-12 bg-black/80 backdrop-blur-sm border border-white/20 hover:border-teal-500 hover:bg-teal-500/20 rounded-full flex items-center justify-center transition-all duration-300 hover:scale-110"
              >
                <Github className="w-5 h-5 text-white hover:text-teal-400 transition-colors duration-300" />
              </button>
              <button
                onClick={() => handleSocialClick("linkedin")}
                className="w-12 h-12 bg-black/80 backdrop-blur-sm border border-white/20 hover:border-blue-500 hover:bg-blue-500/20 rounded-full flex items-center justify-center transition-all duration-300 hover:scale-110"
              >
                <Linkedin className="w-5 h-5 text-white hover:text-blue-400 transition-colors duration-300" />
              </button>
              <button
                onClick={() => handleSocialClick("twitter")}
                className="w-12 h-12 bg-black/80 backdrop-blur-sm border border-white/20 hover:border-sky-500 hover:bg-sky-500/20 rounded-full flex items-center justify-center transition-all duration-300 hover:scale-110"
              >
                <Twitter className="w-5 h-5 text-white hover:text-sky-400 transition-colors duration-300" />
              </button>
              <button
                onClick={() => handleSocialClick("instagram")}
                className="w-12 h-12 bg-black/80 backdrop-blur-sm border border-white/20 hover:border-pink-500 hover:bg-pink-500/20 rounded-full flex items-center justify-center transition-all duration-300 hover:scale-110"
              >
                <Instagram className="w-5 h-5 text-white hover:text-pink-400 transition-colors duration-300" />
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Scroll Indicator */}
      <div
        className={`absolute bottom-8 left-1/2 transform -translate-x-1/2 transition-all duration-1000 delay-1500 ${
          isVisible ? "translate-y-0 opacity-100" : "translate-y-4 opacity-0"
        }`}
      >
        <div className="w-6 h-10 border-2 border-gray-600 rounded-full flex justify-center hover:border-teal-500 transition-colors duration-300 cursor-pointer">
          <div className="w-0.5 h-3 bg-teal-400 rounded-full mt-2 animate-bounce"></div>
        </div>
      </div>
    </section>
  )
}
